// Recebe o payload da plataforma (event=cases.recovered) e monta os e-mails.
const first = $input.first();
const body = first && first.json && first.json.body ? first.json.body : (first ? first.json : {});
const cases = Array.isArray(body.cases) ? body.cases : [];
const supervisorEmails = Array.isArray(body.supervisorEmails) ? body.supervisorEmails : [];
const summary = body.summary || { count: cases.length, totalAmount: 0 };

function brl(v) {
  return Number(v || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

const out = [];

// 1) Um e-mail para o atendente responsavel de cada caso da carteira dele.
for (const c of cases) {
  if (!c.agent || !c.agent.email) continue;
  const promessa = c.hadActivePromise ? ' (o cliente tinha promessa ativa)' : '';
  const assunto = c.hadActivePromise
    ? 'Promessa cumprida - cliente regularizou'
    : 'Cliente regularizou o pagamento';
  out.push({
    json: {
      tipo: 'atendente',
      to: c.agent.email,
      subject: assunto,
      html: '<p>Ola ' + (c.agent.name || '') + ',</p>' +
            '<p><strong>' + c.customerName + '</strong> regularizou o pagamento (' + brl(c.recoveredAmount) + ')' + promessa + '.</p>' +
            '<p>Caso: ' + c.caseId + '</p>'
    }
  });
}

// 2) Um resumo consolidado para a supervisao.
if (supervisorEmails.length > 0) {
  out.push({
    json: {
      tipo: 'supervisao',
      to: supervisorEmails.join(','),
      subject: summary.count === 1
        ? '1 cliente regularizou o pagamento'
        : summary.count + ' clientes regularizaram o pagamento',
      html: '<p>' + summary.count + ' cliente(s) regularizaram o pagamento nesta sincronizacao (' +
            brl(summary.totalAmount) + ' recuperado).</p>'
    }
  });
}

// Sem destinatarios: retorna vazio (o webhook ja respondeu 200 no recebimento).
return out;
